import pg from 'pg';
import {PostgresAgentDefinitions} from '../../dist/index.js';
const phase=process.env.APP_MIXER_TEST_PHASE,pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${process.env.APP_MIXER_TEST_SCHEMA}`}),hold=()=>new Promise(()=>{});
const store=new PostgresAgentDefinitions({enabled:true,clock:()=>200,authorize:()=>true,query:(sql,args)=>pool.query(sql,args),transaction:async operation=>{const client=await pool.connect();try{await client.query('BEGIN');const result=await operation(async(sql,args)=>{if(phase==='before-evidence'&&sql.startsWith('INSERT INTO app_mixer_agent_definition_control_audit ')){process.send(phase);await hold();}return client.query(sql,args);});await client.query('COMMIT');if(phase==='after-commit'){process.send(phase);await hold();}return result;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}});
const manifest={manifestVersion:1,tenantId:'tenant',agentId:'agent',name:'Agent',owner:{kind:'organization',id:'org'},administrators:['admin'],servicePrincipalId:'service',model:{provider:'local',model:'model'},allowedCapabilities:[],lifecycle:{enabled:false,maxAttempts:2,runTimeoutMs:1000},quotas:{maxConcurrentRuns:1,maxTokensPerRun:100,maxRunsPerDay:10}};
try{await store.save({tenantId:'tenant',principalId:'worker'},manifest,1,{action:'suspend'});throw Error('Expected termination');}catch(error){process.send({error:String(error)});process.exitCode=1;await pool.end();}
